"use strict"

/** @typedef {import("./Resolver").FileSystem} FileSystem */
/** @typedef {import("./Resolver").StringCallback} StringCallback */
/** @typedef {import("./Resolver").SyncFileSystem} SyncFileSystem */

// eslint-disable-next-line jsdoc/reject-function-type
/** @typedef {Function} SyncOrAsyncFunction */
// eslint-disable-next-line jsdoc/reject-any-type
/** @typedef {any} ResultOfSyncOrAsyncFunction */

/**
 * @param {SyncFileSystem} fs file system implementation
 * @constructor
 */
/** @type {FileSystem["lstat"]} */ /** @type {SyncOrAsyncFunction | undefined} */
/** @type {NodeJS.ErrnoException | null} */
/** @type {ResultOfSyncOrAsyncFunction} */
/** @type {SyncFileSystem["lstatSync"]} */
/** @type {FileSystem["stat"]} */ /** @type {SyncOrAsyncFunction | undefined} */
/** @type {NodeJS.ErrnoException | null} */
/** @type {ResultOfSyncOrAsyncFunction} */
/** @type {SyncFileSystem["statSync"]} */
/** @type {FileSystem["readdir"]} */ /** @type {SyncOrAsyncFunction | undefined} */
/** @type {Exclude<Parameters<FileSystem["readdir"]>[1], (err: NodeJS.ErrnoException | null, files: string[]) => void>} */
/** @type {NodeJS.ErrnoException | null} */
/** @type {ResultOfSyncOrAsyncFunction} */
/** @type {SyncFileSystem["readdirSync"]} */
/** @type {Parameters<SyncFileSystem["readdirSync"]>[1]} */
/** @type {FileSystem["readFile"]} */ /** @type {SyncOrAsyncFunction | undefined} */
/** @type {NodeJS.ErrnoException | null} */
/** @type {ResultOfSyncOrAsyncFunction} */
/** @type {SyncFileSystem["readFileSync"]} */
/** @type {FileSystem["readlink"]} */ /** @type {SyncOrAsyncFunction | undefined} */
/** @type {Exclude<Parameters<FileSystem["readlink"]>[1], StringCallback>} */
/** @type {NodeJS.ErrnoException | null} */
/** @type {ResultOfSyncOrAsyncFunction} */
/** @type {SyncFileSystem["readlinkSync"]} */
/** @type {Parameters<SyncFileSystem["readlinkSync"]>[1]} */
/** @type {FileSystem["readJson"]} */
/** @type {NodeJS.ErrnoException | Error | null} */
/** @type {SyncFileSystem["readJsonSync"]} */
/** @type {FileSystem["realpath"]} */ /** @type {SyncOrAsyncFunction | undefined} */
/** @type {Exclude<Parameters<NonNullable<FileSystem["realpath"]>>[1], StringCallback>} */
/** @type {NodeJS.ErrnoException | null} */
/** @type {ResultOfSyncOrAsyncFunction} */
/** @type {SyncFileSystem["realpathSync"]} */
/** @type {Parameters<NonNullable<SyncFileSystem["realpathSync"]>>[1]} */

function SyncAsyncFileSystemDecorator(fs) {
  this.fs = fs

  this.lstat = undefined
  this.lstatSync = undefined
  const { lstatSync } = fs
  if (lstatSync) {
    this.lstat = (arg, options, callback) => {
      let result
      try {
        result = callback
          ? lstatSync.call(fs, arg, options)
          : lstatSync.call(fs, arg)
      } catch (err) {
        return (callback || options)(err)
      }

      ;(callback || options)(null, result)
    }
    this.lstatSync = (arg, options) => lstatSync.call(fs, arg, options)
  }

  this.stat = (arg, options, callback) => {
    let result
    try {
      result = callback ? fs.statSync(arg, options) : fs.statSync(arg)
    } catch (err) {
      return (callback || options)(err)
    }

    ;(callback || options)(null, result)
  }
  this.statSync = (arg, options) => fs.statSync(arg, options)

  this.readdir = (arg, options, callback) => {
    let result
    try {
      result = callback ? fs.readdirSync(arg, options) : fs.readdirSync(arg)
    } catch (err) {
      return (callback || options)(err, [])
    }

    ;(callback || options)(null, result)
  }
  this.readdirSync = (arg, options) => fs.readdirSync(arg, options)

  this.readFile = (arg, options, callback) => {
    let result
    try {
      result = callback ? fs.readFileSync(arg, options) : fs.readFileSync(arg)
    } catch (err) {
      return (callback || options)(err)
    }

    ;(callback || options)(null, result)
  }
  this.readFileSync = (arg, options) => fs.readFileSync(arg, options)

  this.readlink = (arg, options, callback) => {
    let result
    try {
      result = callback ? fs.readlinkSync(arg, options) : fs.readlinkSync(arg)
    } catch (err) {
      return (callback || options)(err)
    }

    ;(callback || options)(null, result)
  }
  this.readlinkSync = (arg, options) => fs.readlinkSync(arg, options)

  this.readJson = undefined
  this.readJsonSync = undefined
  const { readJsonSync } = fs
  if (readJsonSync) {
    this.readJson = (arg, callback) => {
      let result
      try {
        result = readJsonSync.call(fs, arg)
      } catch (err) {
        return callback(err)
      }

      callback(null, result)
    }
    this.readJsonSync = (arg) => readJsonSync.call(fs, arg)
  }

  this.realpath = undefined
  this.realpathSync = undefined
  const { realpathSync } = fs
  if (realpathSync) {
    this.realpath = (arg, options, callback) => {
      let result
      try {
        result = callback
          ? realpathSync.call(fs, arg, options)
          : realpathSync.call(fs, arg)
      } catch (err) {
        return (callback || options)(err)
      }

      ;(callback || options)(null, result)
    }
    this.realpathSync = (arg, options) => realpathSync.call(fs, arg, (options))
  }
}

module.exports = SyncAsyncFileSystemDecorator
